int patch_mac(const char *srn, char *m0, char *m1) {
	int i=0;
	int ret = 0;

	if(!*srn) {
		printf("no srn\n");
		return -1;
	}

	while(strlen(sr[i])) {
		if(strncmp(srn, sr[i], strlen(srn))==0) {
			printf("get mac[%s][%s] w/ src:%s\n", mac_0[i], sb1[i], sr[i]);
			strncpy(m0, mac_0[i], strlen(mac_0[i]));
			strncpy(m1, sb1[i], strlen(sb1[i]));
			ret = 1;
			break;
		}
		i++;
	}

	return ret;
}

